36	// Event 是包裹轨迹中的一条记录，按提交顺序追加。
37	type Event struct {
38		Op         string    `json:"op"`                   // 收件 | 交接 | 退回 | 出站 | 回执 | 冻结 | 解除冻结 | 收回 | 续接 | 撤销回执 | 退件 | 发运 | 接收 | 改址
39		Station    string    `json:"station"`              // 与该操作有关的站点（退回时为退回目的站，即原交接源站；冻结/解除冻结为包裹所在站点；收回/续接/撤销回执/退件为批次出发站；发运时为源站，接收时为目的站；改址时为源站，包裹不移动）
40		Time       time.Time `json:"time"`                 // 发生时间
41		Request    string    `json:"request,omitempty"`    // 交接/退回/回执/收回/续接/撤销/退件/接收/改址请求号（收件、出站、发运记录为空）
42		From       string    `json:"from,omitempty"`       // 退回源站（原交接目的站，仅退回记录有）、发运/接收源站（仅发运、接收记录有）或改址前有效目的站（仅改址记录有）
43		To         string    `json:"to,omitempty"`         // 发运/接收目的站（仅发运、接收记录有）或改址后的新目的站（仅改址记录有）
44		Shipment   string    `json:"shipment,omitempty"`   // 运输单号（仅发运、接收、改址记录有）
45		Reason     string    `json:"reason,omitempty"`     // 退回原因（仅退回记录有）、回执失败原因（仅失败回执有）、冻结原因（仅冻结记录有）、中止原因（仅收回记录有）、续接原因（仅续接记录有）、撤销原因（仅撤销回执记录有）、退件原因（仅退件记录有）或改址原因（仅改址记录有）
46		RefRequest string    `json:"refRequest,omitempty"` // 被退回的原交接请求号（仅退回记录有）、被撤销的原回执请求号（仅撤销回执记录有）或被退件的原签收回执请求号（仅退件记录有）
47		Batch      string    `json:"batch,omitempty"`      // 配送批次号（仅出站、回执、收回、续接、撤销回执、退件记录有；续接时为新批次号）
48		FromBatch  string    `json:"fromBatch,omitempty"`  // 续接原批次号（仅续接记录有）
49		Courier    string    `json:"courier,omitempty"`    // 配送员（仅出站、续接记录有；续接时为新配送员）
50		Result     string    `json:"result,omitempty"`     // 回执结果：签收 | 失败（仅回执记录有）
51		// Incident 为冻结/解除冻结记录的异常单号；解除冻结时另外用 Request 存解除请求号、Note 存处理说明。
52		Incident string `json:"incident,omitempty"`
53		Note     string `json:"note,omitempty"`
54	}
55	
56	// Parcel 是一件包裹的台账信息。
57	type Parcel struct {
58		ID         string    `json:"id"`
59		Station    string    `json:"station"`    // 当前归属站点
60		Status     string    `json:"status"`     // 当前状态
61		Registered time.Time `json:"registered"` // 收件时间
62		Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
63	}
64	
65	// HandoffResult 记录一次成功交接，用于请求号去重与结果重放。
66	type HandoffResult struct {
67		Request    string    `json:"request"`
68		From       string    `json:"from"`
69		To         string    `json:"to"`
70		Parcels    []string  `json:"parcels"` // 按首次提交时给出的顺序保存
71		Time       time.Time `json:"time"`
72		ReturnedBy string    `json:"returnedBy,omitempty"` // 已成功退回该交接的退回请求号（未退回为空）
73	}
74	
75	// ReturnResult 记录一次成功的整批退回，用于退回请求号去重与结果重放。
76	type ReturnResult struct {
77		Request string    `json:"request"` // 退回请求号
78		Handoff string    `json:"handoff"` // 被退回的原交接请求号
79		From    string    `json:"from"`    // 退回源站（原交接目的站）
80		To      string    `json:"to"`      // 退回目的站（原交接源站）
81		Reason  string    `json:"reason"`
82		Parcels []string  `json:"parcels"` // 原交接批次，按原交接保存的顺序
83		Time    time.Time `json:"time"`
84	}
85	
86	// ReceiptEntry 是批次内一件包裹的当前回执记录（被新回执取代的已撤销条目由
87	// 台账级 Receipts 结果表与撤销记录共同保留）。
88	type ReceiptEntry struct {
89		Request string    `json:"request"`          // 回执请求号
90		Result  string    `json:"result"`           // 签收 | 失败
91		Reason  string    `json:"reason,omitempty"` // 失败原因（仅失败回执有）
92		Time    time.Time `json:"time"`
93		// RevokedBy 为撤销该回执的撤销请求号（未撤销为空）；撤销后该条不再计入有效回执。
94		RevokedBy string `json:"revokedBy,omitempty"`
95		// ReturnedBy 为对该签收办理实物退件的退件请求号（未退件为空）；与 RevokedBy
96		// 互斥。退件不取消有效回执，该条仍计入批次回执进度。
97		ReturnedBy string `json:"returnedBy,omitempty"`
98	}
99	
100	// BatchResult 记录一次成功的配送批次出站，用于批次号去重、结果重放与批次查询。
101	// 成员按首次提交时给出的顺序保存，保存后不可修改；批次完成后批次号也不能复用。
102	type BatchResult struct {
103		Batch    string                   `json:"batch"`
104		Station  string                   `json:"station"`  // 出发站
105		Courier  string                   `json:"courier"`  // 配送员
106		Parcels  []string                 `json:"parcels"`  // 批次成员，按首次提交顺序
107		Time     time.Time                `json:"time"`     // 出站时间
108		Receipts map[string]*ReceiptEntry `json:"receipts"` // 逐件回执，按包裹编号索引（未回执的包裹不在其中）
109		// AbortedBy 为中止该批次的中止请求号（未中止为空）；中止永久生效，批次不得复用。
110		AbortedBy string `json:"abortedBy,omitempty"`
111		// TransferredBy 为把最后待配送件转走、永久关闭该批次为“已转交”的续接请求号
112		// （尚未永久转交为空）。途中分批续接期间该批次仍配送中，各次续接记录见 Transfers；
113		// 转走最后一件待配送件时才在此置位，与中止互斥，批次永久关闭、不得复用。
114		TransferredBy string `json:"transferredBy,omitempty"`
115		// Transfers 为该批次作为原批次发生过的各次续接的请求号，按提交顺序追加。
116		// 分批续接只转走部分待配送件：原批次保留件继续由原配送员按原批次配送，
117		// 故批次仍开放、仍可回执、中止或再次续接；旧版数据文件只有最后一次（整批）
118		// 续接的 transferredBy，载入时迁移到本列表。
119		Transfers []string `json:"transfers,omitempty"`
120		// RelayedFrom 与 RelayRequest 仅对续接创建的新批次有效：分别记录来源批次号
121		// 与创建本批次的续接请求号（普通出站批次为空）。
122		RelayedFrom  string `json:"relayedFrom,omitempty"`
123		RelayRequest string `json:"relayRequest,omitempty"`
124	}
125	
126	// openParcels 返回该批次当前仍由本批次配送的待配送成员（无有效回执且未转交），
127	// 按原成员顺序。载入校验保证 Transfers 引用的续接请求均存在。
128	func (b *BatchResult) openParcels(ledger *ledgerFile) []string {
129		out := make([]string, 0, len(b.Parcels))
130		for _, pid := range b.Parcels {
131			if e, done := b.Receipts[pid]; done && e.RevokedBy == "" {
132				continue // 已有有效回执
133			}
134			transferred := false
135			for _, req := range b.Transfers {
136				if t := ledger.Transfers[req]; t != nil {
137					for _, id := range t.Parcels {
138						if id == pid {
139							transferred = true
140							break
141						}
142					}
143				}
144				if transferred {
145					break
146				}
147			}
148			if !transferred {
149				out = append(out, pid)
150			}
151		}
152		return out
153	}
154	
155	// Effective 返回批次当前有效（未撤销）的回执数量。
156	func (b *BatchResult) Effective() int {
157		n := 0
158		for _, e := range b.Receipts {
159			if e != nil && e.RevokedBy == "" {
160				n++
161			}
162		}
163		return n
164	}
165	
166	// Done 报告批次是否已完成（全部成员均有未撤销的有效回执）。
167	func (b *BatchResult) Done() bool { return b.Effective() == len(b.Parcels) }
168	
169	// ReceiptResult 记录一次成功的逐件回执，用于回执请求号去重与结果重放。
170	// 回执结果永久保留：即使之后被撤销，回执请求号也不删除、不释放。
171	type ReceiptResult struct {
172		Request string    `json:"request"` // 回执请求号
173		Batch   string    `json:"batch"`   // 所属配送批次号
174		Parcel  string    `json:"parcel"`  // 包裹编号
175		Result  string    `json:"result"`  // 签收 | 失败
176		Reason  string    `json:"reason,omitempty"`
177		Time    time.Time `json:"time"`
178		// RevokedBy 为撤销该回执的撤销请求号（未撤销为空）；每条回执只能被撤销一次。
179		RevokedBy string `json:"revokedBy,omitempty"`
180		// ReturnedBy 为对该签收回执办理签收后退件的退件请求号（未退件为空）。
181		// 只有结果为签收的回执可被退件，且每条签收只能成功退件一次；退件与撤销
182		// 互斥，二者不会同时置位。原签收事实永久保留、仍计有效回执。
183		ReturnedBy string `json:"returnedBy,omitempty"`
184	}
185	
186	// ReceiptReturnResult 记录一次成功的签收后实物退件，用于退件请求号去重与结果重放。
187	// 退件表示已真实签收的包裹实物送回该次配送的出发站：包裹恢复出发站在站，原签收
188	// 事实永久保留、仍计该批次的有效回执，原批次状态与进度不变，不恢复旧批次配送，
189	// 也不能再撤销该签收。退件算新流转，不恢复旧交接的退回资格。
190	// 退件请求号独立去重，可与其他业务编号同名；失败的首次退件不占用请求号。
191	type ReceiptReturnResult struct {
192		Request string    `json:"request"` // 退件请求号
193		Receipt string    `json:"receipt"` // 被退件的原签收回执请求号
194		Batch   string    `json:"batch"`   // 原配送批次号（取自原回执，不可另选）
195		Parcel  string    `json:"parcel"`  // 包裹编号（取自原回执，不可另选）
196		Station string    `json:"station"` // 接收站（该次配送出发站，取自原批次）
197		Reason  string    `json:"reason"`  // 清理后的退件原因
198		Time    time.Time `json:"time"`    // 退件时间
199	}
200	
201	// FreezeResult 记录一次成功的异常冻结，用于异常单号去重与结果重放。
202	// 异常单号标识一次异常，解除后也不能复用；失败的首次冻结不占用异常单号。
203	type FreezeResult struct {
204		Incident string    `json:"incident"` // 异常单号
205		Parcel   string    `json:"parcel"`   // 被冻结的包裹编号
206		Station  string    `json:"station"`  // 冻结时包裹所在站点（冻结与解除期间均不变）
207		Reason   string    `json:"reason"`   // 清理后的冻结原因
208		Time     time.Time `json:"time"`     // 冻结时间
209		// ReleasedBy 为解除该异常单的解除请求号（未解除为空）；解除后异常单永久保留、不得复用。
210		ReleasedBy string `json:"releasedBy,omitempty"`
211	}
212	
213	// UnfreezeResult 记录一次成功的解除冻结，用于解除请求号去重与结果重放。
214	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名；失败的首次解除不占用请求号。
215	type UnfreezeResult struct {
216		Request  string    `json:"request"`  // 解除请求号
217		Incident string    `json:"incident"` // 被解除的异常单号
218		Parcel   string    `json:"parcel"`   // 对应包裹编号
219		Note     string    `json:"note"`     // 清理后的处理说明
220		Time     time.Time `json:"time"`     // 解除时间
221	}
222	
223	// AbortResult 记录一次成功的配送批次中止，用于中止请求号去重与结果重放。
224	// 中止表示配送员已将该批次全部尚未回执的包裹实物收回出发站：批次永久关闭，
225	// 原成员顺序、配送员与出站时间保留不变，已回执成员及其回执完全保留。
226	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名；失败的首次中止不占用请求号。
227	type AbortResult struct {
228		Request string    `json:"request"` // 中止请求号
229		Batch   string    `json:"batch"`   // 被中止的配送批次号
230		Station string    `json:"station"` // 出发站（收回目的站，取自原批次）
231		Reason  string    `json:"reason"`  // 清理后的中止原因
232		Parcels []string  `json:"parcels"` // 首次收回的未回执包裹，按原批次成员顺序
233		Time    time.Time `json:"time"`    // 中止时间
234	}
235	
236	// TransferResult 记录一次成功的配送途中续接，用于续接请求号去重与结果重放。
237	// 续接表示原配送员把原批次部分或全部尚未回执的包裹在配送途中交给另一配送员：
238	// 新批次按原成员顺序接纳本次选中件继续配送，包裹保持“配送中”及原站点；
239	// 未选中的余件继续留在原批次由原配送员配送。只转交部分待配送件时原批次仍
240	// 开放（仍配送中，可继续回执、中止或再次续接），转走最后一件待配送件时原批次
241	// 才永久关闭为“已转交”。续接请求号独立去重，可与批次号、包裹号及其他业务
242	// 编号同名；失败的首次续接不占用请求号。
243	type TransferResult struct {
244		Request     string    `json:"request"`     // 续接请求号
245		FromBatch   string    `json:"fromBatch"`   // 原批次号
246		ToBatch     string    `json:"toBatch"`     // 新批次号
247		Station     string    `json:"station"`     // 出发站（沿用原批次）
248		FromCourier string    `json:"fromCourier"` // 原配送员（取自原批次）
249		ToCourier   string    `json:"toCourier"`   // 新配送员
250		Reason      string    `json:"reason"`      // 清理后的续接原因
251		Parcels     []string  `json:"parcels"`     // 本次转交集合，按原批次成员顺序
252		Time        time.Time `json:"time"`        // 接手时间
253		// Explicit 为 true 表示本次续接显式选择了包裹集合；false 表示不选成员、
254		// 取当时全部无有效回执且未转交的待配送件（旧版整批续接记录没有该字段，
255		// 按不选成员处理）。
256		Explicit bool `json:"explicit,omitempty"`
257	}
258	
259	// RevokeResult 记录一次成功的误录回执撤销，用于撤销请求号去重与结果重放。
260	// 撤销只更正台账：经核实包裹实际仍由原配送员配送，撤销错误的签收或失败登记，
261	// 不收回实物。原回执结果与轨迹永久保留并标记已撤销，回执请求号不删除也不释放。
262	// 撤销请求号独立去重，可与批次号、包裹号、回执请求号及其他业务编号同名；
263	// 失败的首次撤销不占用请求号。
264	type RevokeResult struct {
265		Request string    `json:"request"` // 撤销请求号
266		Receipt string    `json:"receipt"` // 被撤销的原回执请求号
267		Batch   string    `json:"batch"`   // 所属配送批次号（取自原回执，不可另选）
268		Parcel  string    `json:"parcel"`  // 包裹编号（取自原回执，不可另选）
269		Reason  string    `json:"reason"`  // 清理后的撤销原因
270		Time    time.Time `json:"time"`    // 撤销时间
271	}
272	
273	// ShipmentResult 记录一次成功的站间发运，用于运输单号去重、结果重放与运输单查询。
274	// 发运表示整单包裹已离开源站、尚未到达目的站：整单转为“站间在途”，归属站点暂记
275	// 源站，成员按首次提交顺序保存，保存后不可修改。运输单号独立于已有各类编号，
276	// 接收后也不释放；失败的首次发运不占用运输单号。
277	type ShipmentResult struct {
278		Shipment string    `json:"shipment"` // 运输单号
279		From     string    `json:"from"`     // 源站
280		To       string    `json:"to"`       // 目的站
281		Parcels  []string  `json:"parcels"`  // 成员，按首次提交顺序
282		Time     time.Time `json:"time"`     // 发运时间
283		// ReceivedBy 为使该运输单达到全部接收的接收请求号（尚未全部接收为空）；
284		// 全部接收永久生效，运输单号不释放。分批到站时可能经历多次接收，
285		// 每次接收记录于接收结果表，是否全部接收按各次接收事实统计。
286		ReceivedBy string `json:"receivedBy,omitempty"`
287		// Reroutes 为该运输单各次改址的改址请求号，按提交顺序追加（未改址为空）。
288		// 改址只变更当时全部未收件的有效目的站：原目的站、成员、发运结果与已有
289		// 接收事实永久保留。旧版数据文件没有该字段，按未改址处理。
290		Reroutes []string `json:"reroutes,omitempty"`
291	}
292	
293	// ReceiveResult 记录一次成功的到站接收，用于接收请求号去重与结果重放。
294	// 接收表示运输单的一批成员已到达目的站：按发运保存顺序将本次成员改归目的站、
295	// 恢复在站；全部成员到齐后运输单永久标记为已接收。接收请求号与运输单号及已有
296	// 各类编号分属独立去重范围，允许同名；失败的首次接收不占用请求号。
297	type ReceiveResult struct {
298		Request  string    `json:"request"`  // 接收请求号
299		Shipment string    `json:"shipment"` // 被接收的运输单号
300		Station  string    `json:"station"`  // 接收站点（即运输单目的站）
301		Parcels  []string  `json:"parcels"`  // 本次接收的成员，按发运保存顺序
302		Time     time.Time `json:"time"`     // 接收时间
303		// Explicit 为 true 表示本次接收显式选择了包裹集合；false 表示不选成员、
304		// 接收当时全部尚未接收件（旧版整单接收记录没有该字段，按不选成员处理）。
305		Explicit bool `json:"explicit,omitempty"`
306	}
307	
308	// RerouteResult 记录一次成功的运输途中改址，用于改址请求号去重与结果重放。
309	// 改址表示一张运输单当前全部未收件改送另一目的站：不另建运输单、不重新发运，
310	// 成员仍归源站、保持站间在途及作业限制，只变更余件的有效目的站；原成员、发运
311	// 结果、已有接收事实与轨迹永久保留。集合为受理时全部未收件，按发运保存顺序。
312	// 改址请求号独立去重，可与运输单号及其他业务编号同名；失败的首次改址不占用请求号。
313	type RerouteResult struct {
314		Request  string    `json:"request"`  // 改址请求号
315		Shipment string    `json:"shipment"` // 被改址的运输单号
316		From     string    `json:"from"`     // 改址前的有效目的站（首次为运输单原目的站）
317		To       string    `json:"to"`       // 新目的站（不同于改址前有效目的站与源站）
318		Reason   string    `json:"reason"`   // 清理后的改址原因
319		Parcels  []string  `json:"parcels"`  // 受理时全部未收件，按发运保存顺序
320		Time     time.Time `json:"time"`     // 改址时间
321	}
322	
323	// ledgerFile 是本地数据文件的磁盘结构。
324	type ledgerFile struct {
325		Version   int                        `json:"version"`
326		Parcels   map[string]*Parcel         `json:"parcels"`
327		Handoffs  map[string]*HandoffResult  `json:"handoffs"`
328		Returns   map[string]*ReturnResult   `json:"returns"`
329		Batches   map[string]*BatchResult    `json:"batches"`
330		Receipts  map[string]*ReceiptResult  `json:"receipts"`
331		Freezes   map[string]*FreezeResult   `json:"freezes"`   // 以异常单号为键（含已解除的异常单，永久保留）
332		Unfreezes map[string]*UnfreezeResult `json:"unfreezes"` // 以解除请求号为键
333		Aborts    map[string]*AbortResult    `json:"aborts"`    // 以中止请求号为键
334		Transfers map[string]*TransferResult `json:"transfers"` // 以续接请求号为键
335		Revokes   map[string]*RevokeResult   `json:"revokes"`   // 以撤销请求号为键
336		// ReceiptReturns 以退件请求号为键，记录已真实签收包裹送回配送出发站的退件结果。
337		// 旧版数据文件没有该字段：按空表处理，旧有效台账直接使用。
338		ReceiptReturns map[string]*ReceiptReturnResult `json:"receiptReturns,omitempty"`
339		Shipments      map[string]*ShipmentResult      `json:"shipments"` // 以运输单号为键（含已接收的运输单，永久保留）
340		Receives       map[string]*ReceiveResult       `json:"receives"`  // 以接收请求号为键
341		Reroutes       map[string]*RerouteResult       `json:"reroutes"`  // 以改址请求号为键
342	}
343	
344	// Store 是一个数据文件对应的包裹站点交接台账。
345	type Store struct {
346		path string
347		data ledgerFile
348	}
349	
350	var (
351		// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
352		ErrCorrupt = errors.New("数据文件已损坏")
353		// ErrNotFound 表示包裹编号在台账中不存在。
354		ErrNotFound = errors.New("包裹不存在")
355	)
356	
357	// Open 打开（或在文件不存在时建立）一个本地台账。
358	// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
359	func Open(path string) (*Store, error) {
360		s := &Store{path: path}
361		raw, err := os.ReadFile(path)
362		if err != nil {
363			if os.IsNotExist(err) {
364				s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{},
365					Returns: map[string]*ReturnResult{}, Batches: map[string]*BatchResult{}, Receipts: map[string]*ReceiptResult{},
366					Freezes: map[string]*FreezeResult{}, Unfreezes: map[string]*UnfreezeResult{}, Aborts: map[string]*AbortResult{},
367					Transfers: map[string]*TransferResult{}, Revokes: map[string]*RevokeResult{}, Shipments: map[string]*ShipmentResult{},
368					Receives: map[string]*ReceiveResult{}, Reroutes: map[string]*RerouteResult{},
369					ReceiptReturns: map[string]*ReceiptReturnResult{}}
370				return s, nil
371			}
372			return nil, fmt.Errorf("读取数据文件失败: %w", err)
373		}
374		if len(bytes.TrimSpace(raw)) == 0 {
375			return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
376		}
377		if err := json.Unmarshal(raw, &s.data); err != nil {
378			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
379		}
380		if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
381			return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
382		}
383		// 早期版本的数据文件没有 returns/batches/receipts/freeze/abort/revoke 相关字段：按空表处理，无需手工修改。
384		if s.data.Returns == nil {
385			s.data.Returns = map[string]*ReturnResult{}
386		}
387		if s.data.Batches == nil {
388			s.data.Batches = map[string]*BatchResult{}
389		}
390		if s.data.Receipts == nil {
391			s.data.Receipts = map[string]*ReceiptResult{}
392		}
393		if s.data.Freezes == nil {
394			s.data.Freezes = map[string]*FreezeResult{}
395		}
396		if s.data.Unfreezes == nil {
397			s.data.Unfreezes = map[string]*UnfreezeResult{}
398		}
399		if s.data.Aborts == nil {
400			s.data.Aborts = map[string]*AbortResult{}
401		}
402		if s.data.Transfers == nil {
403			s.data.Transfers = map[string]*TransferResult{}
404		}
405		if s.data.Revokes == nil {
406			s.data.Revokes = map[string]*RevokeResult{}
407		}
408		// 早期版本的数据文件没有 receiptReturns 字段：按空表处理，旧有效台账直接使用。
409		if s.data.ReceiptReturns == nil {
410			s.data.ReceiptReturns = map[string]*ReceiptReturnResult{}
411		}
412		// 早期版本的数据文件没有 shipments/receives 字段：按空表处理，无需手工修改。
413		if s.data.Shipments == nil {
414			s.data.Shipments = map[string]*ShipmentResult{}
415		}
416		if s.data.Receives == nil {
417			s.data.Receives = map[string]*ReceiveResult{}
418		}
419		// 早期版本的数据文件没有 reroutes 字段：按空表处理（各运输单均未改址），无需手工修改。
420		if s.data.Reroutes == nil {
421			s.data.Reroutes = map[string]*RerouteResult{}
422		}
423		for _, b := range s.data.Batches {
424			if b != nil && b.Receipts == nil {
425				b.Receipts = map[string]*ReceiptEntry{}
426			}
427		}
428		// 早期版本的续接一次转走全部未回执件，原批次只用 transferredBy 记录最后一次
429		// （也是唯一一次）续接；现把它迁移到按提交顺序的 transfers 列表，旧有效台账
430		// 无需手工修改即可直接使用。
431		for _, b := range s.data.Batches {
432			if b == nil || len(b.Transfers) > 0 {
433				continue
434			}
435			if b.TransferredBy != "" {
436				b.Transfers = []string{b.TransferredBy}
437			}
438		}
439		if err := s.data.validate(); err != nil {
440			return nil, err
441		}
442		return s, nil
443	}
444	
445	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
446	func (l *ledgerFile) validate() error {
447		for id, p := range l.Parcels {
448			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
449				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
450			}
451			switch p.Status {
452			case statusInStation, statusDelivering, statusSigned, statusFrozen, statusInTransit:
453			default:
454				return fmt.Errorf("%w: 包裹 %q 的状态 %q 不受支持", ErrCorrupt, id, p.Status)
455			}
456			for i, e := range p.Trail {
457				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
458					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
459				}
460				if e.Op == "退回" {
461					if e.Request == "" || e.Reason == "" || e.From == "" {
462						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
463					}
464					if _, ok := l.Handoffs[e.RefRequest]; !ok {
465						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
466					}
467				}
468				if e.Op == "出站" {
469					if e.Batch == "" || e.Courier == "" {
470						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹缺少批次号或配送员", ErrCorrupt, id, i+1)
471					}
472					if _, ok := l.Batches[e.Batch]; !ok {
473						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
474					}
475				}
476				if e.Op == "回执" {
477					if e.Batch == "" || e.Request == "" || (e.Result != resultSigned && e.Result != resultFailed) {
478						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹缺少批次号、请求号或结果无效", ErrCorrupt, id, i+1)
479					}
480					if e.Result == resultFailed && e.Reason == "" {
481						return fmt.Errorf("%w: 包裹 %q 第 %d 条失败回执轨迹缺少原因", ErrCorrupt, id, i+1)
482					}
483					if _, ok := l.Batches[e.Batch]; !ok {
484						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
485					}
486				}
487				if e.Op == "撤销回执" {
488					if e.Batch == "" || e.Request == "" || e.RefRequest == "" || e.Reason == "" {
489						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹缺少批次号、撤销请求号、原回执请求号或原因", ErrCorrupt, id, i+1)
490					}
491					b, ok := l.Batches[e.Batch]
492					if !ok || b == nil {
493						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
494					}
495					if e.Station != b.Station {
496						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹的站点 %q 与批次 %q 出发站 %q 不一致",
497							ErrCorrupt, id, i+1, e.Station, e.Batch, b.Station)
498					}
499					rv, ok := l.Revokes[e.Request]
500					if !ok || rv == nil {
501						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的撤销请求 %q", ErrCorrupt, id, i+1, e.Request)
502					}
503					if rv.Receipt != e.RefRequest || rv.Batch != e.Batch || rv.Parcel != id || rv.Reason != e.Reason || !rv.Time.Equal(e.Time) {
504						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹与撤销请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
505					}
506				}
507				if e.Op == "退件" {
508					if e.Batch == "" || e.Request == "" || e.RefRequest == "" || e.Reason == "" {
509						return fmt.Errorf("%w: 包裹 %q 第 %d 条退件轨迹缺少批次号、退件请求号、原签收请求号或原因", ErrCorrupt, id, i+1)
510					}
511					b, ok := l.Batches[e.Batch]
512					if !ok || b == nil {
513						return fmt.Errorf("%w: 包裹 %q 第 %d 条退件轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
514					}
515					if e.Station != b.Station {
516						return fmt.Errorf("%w: 包裹 %q 第 %d 条退件轨迹的站点 %q 与批次 %q 出发站 %q 不一致",
517							ErrCorrupt, id, i+1, e.Station, e.Batch, b.Station)
518					}
519					rr, ok := l.ReceiptReturns[e.Request]
520					if !ok || rr == nil {
521						return fmt.Errorf("%w: 包裹 %q 第 %d 条退件轨迹引用了不存在的退件请求 %q", ErrCorrupt, id, i+1, e.Request)
522					}
523					if rr.Receipt != e.RefRequest || rr.Batch != e.Batch || rr.Parcel != id || rr.Reason != e.Reason || !rr.Time.Equal(e.Time) {
524						return fmt.Errorf("%w: 包裹 %q 第 %d 条退件轨迹与退件请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
525					}
526				}
527				if e.Op == "收回" {
528					if e.Batch == "" || e.Request == "" || e.Reason == "" {
529						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹缺少批次号、中止请求号或原因", ErrCorrupt, id, i+1)
530					}
531					a, ok := l.Aborts[e.Request]
532					if !ok || a == nil {
533						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹引用了不存在的中止请求 %q", ErrCorrupt, id, i+1, e.Request)
534					}
535					if a.Batch != e.Batch || a.Station != e.Station || a.Reason != e.Reason || !a.Time.Equal(e.Time) {
536						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹与中止请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
537					}
538					inAbort := false
539					for _, pid := range a.Parcels {
540						if pid == id {
541							inAbort = true
542							break
543						}
544					}
545					if !inAbort {
546						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹不在中止请求 %q 的收回集合中", ErrCorrupt, id, i+1, e.Request)
547					}
548				}
549				if e.Op == "续接" {
550					if e.Batch == "" || e.FromBatch == "" || e.Courier == "" || e.Request == "" || e.Reason == "" {
551						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹缺少新批次号、原批次号、新配送员、续接请求号或原因", ErrCorrupt, id, i+1)
552					}
553					t, ok := l.Transfers[e.Request]
554					if !ok || t == nil {
555						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹引用了不存在的续接请求 %q", ErrCorrupt, id, i+1, e.Request)
556					}
557					if t.FromBatch != e.FromBatch || t.ToBatch != e.Batch || t.ToCourier != e.Courier ||
558						t.Station != e.Station || t.Reason != e.Reason || !t.Time.Equal(e.Time) {
559						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹与续接请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
560					}
561					inTransfer := false
562					for _, pid := range t.Parcels {
563						if pid == id {
564							inTransfer = true
565							break
566						}
567					}
568					if !inTransfer {
569						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹不在续接请求 %q 的转交集合中", ErrCorrupt, id, i+1, e.Request)
570					}
571				}
572				if e.Op == "发运" {
573					if e.Shipment == "" || e.From == "" || e.To == "" {
574						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹缺少运输单号、源站或目的站", ErrCorrupt, id, i+1)
575					}
576					sh, ok := l.Shipments[e.Shipment]
577					if !ok || sh == nil {
578						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹引用了不存在的运输单 %q", ErrCorrupt, id, i+1, e.Shipment)
579					}
580					if sh.From != e.From || sh.To != e.To || e.Station != e.From || !sh.Time.Equal(e.Time) {
581						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹与运输单 %q 记录不一致", ErrCorrupt, id, i+1, e.Shipment)
582					}
583					inShipment := false
584					for _, pid := range sh.Parcels {
585						if pid == id {
586							inShipment = true
587							break
588						}
589					}
590					if !inShipment {
591						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹不在运输单 %q 的成员集合中", ErrCorrupt, id, i+1, e.Shipment)
592					}
593				}
594				if e.Op == "接收" {
595					if e.Shipment == "" || e.Request == "" || e.From == "" || e.To == "" {
596						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹缺少运输单号、接收请求号、源站或目的站", ErrCorrupt, id, i+1)
597					}
598					rv, ok := l.Receives[e.Request]
599					if !ok || rv == nil {
600						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹引用了不存在的接收请求 %q", ErrCorrupt, id, i+1, e.Request)

