1402				return fmt.Errorf("%w: 改址请求号 %q 与运输单 %q 的改址列表关联缺失或重复（出现 %d 次）", ErrCorrupt, req, r.Shipment, linked)
1403			}
1404			member := make(map[string]bool, len(sh.Parcels))
1405			for _, pid := range sh.Parcels {
1406				member[pid] = true
1407			}
1408			seen := make(map[string]bool, len(r.Parcels))
1409			pos := 0 // 集合必须按发运保存顺序排列：在 sh.Parcels 中的位置严格递增
1410			for _, pid := range r.Parcels {
1411				if !member[pid] {
1412					return fmt.Errorf("%w: 改址请求号 %q 的包裹 %q 不属于运输单 %q", ErrCorrupt, req, pid, r.Shipment)
1413				}
1414				if seen[pid] {
1415					return fmt.Errorf("%w: 改址请求号 %q 的集合中包裹 %q 重复", ErrCorrupt, req, pid)
1416				}
1417				seen[pid] = true
1418				at := -1
1419				for i := pos; i < len(sh.Parcels); i++ {
1420					if sh.Parcels[i] == pid {
1421						at = i
1422						break
1423					}
1424				}
1425				if at < 0 {
1426					return fmt.Errorf("%w: 改址请求号 %q 的集合顺序与运输单 %q 的发运保存顺序不一致", ErrCorrupt, req, r.Shipment)
1427				}
1428				pos = at + 1
1429			}
1430			for _, pid := range r.Parcels {
1431				p, ok := l.Parcels[pid]
1432				if !ok {
1433					return fmt.Errorf("%w: 改址请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
1434				}
1435				found := false
1436				for _, e := range p.Trail {
1437					if e.Op == "改址" && e.Request == req {
1438						found = true
1439						break
1440					}
1441				}
1442				if !found {
1443					return fmt.Errorf("%w: 改址请求号 %q 的成员包裹 %q 缺少对应的改址轨迹", ErrCorrupt, req, pid)
1444				}
1445			}
1446		}
1447		// 冻结/解除冻结：先遍历轨迹核对冻结与解除必须成对出现、顺序正确，
1448		// 再核对两张结果表与包裹当前状态的对应关系。
1449		openIncident := make(map[string]string) // 包裹 -> 当前未解除的异常单号（由轨迹推导）
1450		for id, p := range l.Parcels {
1451			var open string
1452			for i, e := range p.Trail {
1453				switch e.Op {
1454				case "冻结":
1455					if open != "" {
1456						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结时异常单 %q 尚未解除，一件包裹同时只能有一张未解除异常单",
1457							ErrCorrupt, id, i+1, open)
1458					}
1459					open = e.Incident
1460				case "解除冻结":
1461					if open != e.Incident {
1462						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除的异常单 %q 与当前冻结 %q 不匹配",
1463							ErrCorrupt, id, i+1, e.Incident, open)
1464					}
1465					open = ""
1466				}
1467			}
1468			if p.Status == statusFrozen && open == "" {
1469				return fmt.Errorf("%w: 包裹 %q 当前为异常冻结，但轨迹中没有未解除的冻结记录", ErrCorrupt, id)
1470			}
1471			if p.Status != statusFrozen && open != "" {
1472				return fmt.Errorf("%w: 包裹 %q 当前状态为 %q，但异常单 %q 尚未解除", ErrCorrupt, id, p.Status, open)
1473			}
1474			if open != "" {
1475				openIncident[id] = open
1476			}
1477		}
1478		for no, f := range l.Freezes {
1479			if f == nil || no != f.Incident || f.Parcel == "" || f.Station == "" || f.Reason == "" || f.Time.IsZero() {
1480				return fmt.Errorf("%w: 异常单号 %q 的冻结结果不完整", ErrCorrupt, no)
1481			}
1482			p, ok := l.Parcels[f.Parcel]
1483			if !ok {
1484				return fmt.Errorf("%w: 异常单 %q 引用了不存在的包裹 %q", ErrCorrupt, no, f.Parcel)
1485			}
1486			if f.ReleasedBy == "" && p.Station != f.Station {
1487				return fmt.Errorf("%w: 异常单 %q 记录的站点 %q 与包裹 %q 当前站点 %q 不一致",
1488					ErrCorrupt, no, f.Station, f.Parcel, p.Station)
1489			}
1490			if f.ReleasedBy != "" {
1491				u, ok := l.Unfreezes[f.ReleasedBy]
1492				if !ok || u == nil || u.Incident != no || u.Parcel != f.Parcel {
1493					return fmt.Errorf("%w: 异常单 %q 标记的解除请求号 %q 无法对应", ErrCorrupt, no, f.ReleasedBy)
1494				}
1495			}
1496		}
1497		activeByParcel := make(map[string]string)
1498		for req, u := range l.Unfreezes {
1499			if u == nil || req != u.Request || u.Incident == "" || u.Parcel == "" || u.Note == "" || u.Time.IsZero() {
1500				return fmt.Errorf("%w: 解除请求号 %q 的解除结果不完整", ErrCorrupt, req)
1501			}
1502			f, ok := l.Freezes[u.Incident]
1503			if !ok || f == nil {
1504				return fmt.Errorf("%w: 解除请求号 %q 引用了不存在的异常单 %q", ErrCorrupt, req, u.Incident)
1505			}
1506			if f.Parcel != u.Parcel {
1507				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 对应的包裹不一致", ErrCorrupt, req, u.Incident)
1508			}
1509			if f.ReleasedBy != req {
1510				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 的解除标记不一致", ErrCorrupt, req, u.Incident)
1511			}
1512		}
1513		for no, f := range l.Freezes {
1514			if f.ReleasedBy != "" {
1515				continue
1516			}
1517			if other, dup := activeByParcel[f.Parcel]; dup {
1518				return fmt.Errorf("%w: 包裹 %q 同时存在两张未解除异常单 %q 与 %q", ErrCorrupt, f.Parcel, other, no)
1519			}
1520			activeByParcel[f.Parcel] = no
1521			if openIncident[f.Parcel] != no {
1522				return fmt.Errorf("%w: 包裹 %q 当前冻结对应的异常单应为 %q，与未解除异常单 %q 不匹配",
1523					ErrCorrupt, f.Parcel, openIncident[f.Parcel], no)
1524			}
1525			if p := l.Parcels[f.Parcel]; p.Status != statusFrozen {
1526				return fmt.Errorf("%w: 异常单 %q 未解除，但包裹 %q 当前状态为 %q", ErrCorrupt, no, f.Parcel, p.Status)
1527			}
1528		}
1529		return nil
1530	}
