1532	// coordinationPath 返回数据文件对应的协调文件（锁文件）路径。
1533	// 相对、绝对及含 .、.. 的写法先归一到同一绝对路径，已存在的符号链接也被解析，
1534	// 确保同一台账的不同路径写法共用同一把锁；首次创建不存在的台账同样适用。
1535	func coordinationPath(path string) (string, error) {
1536		abs, err := filepath.Abs(path)
1537		if err != nil {
1538			return "", fmt.Errorf("解析数据文件路径失败: %w", err)
1539		}
1540		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
1541			abs = resolved
1542		} else if dir, derr := filepath.EvalSymlinks(filepath.Dir(abs)); derr == nil {
1543			abs = filepath.Join(dir, filepath.Base(abs))
1544		}
1545		return abs + ".lock", nil
1546	}
1547	
1548	// OpenForUpdate 在进程间排他协调下打开台账，供会改写台账的命令使用：
1549	// 先取得该台账的锁（其他终端正在作业时等待其完成），再在锁内读取最新已提交
1550	// 数据；调用方随后完成的受理、去重与整次保存都在最新数据上进行，并行效果
1551	// 等同于某个逐次执行顺序。返回的 release 必须在本次命令结束时调用（无论成败）。
1552	// 锁由操作系统随文件描述符管理，持有者进程被强制终止时自动释放，
1553	// 无需人工删除协调文件即可继续作业。
1554	func OpenForUpdate(path string) (s *Store, release func(), err error) {
1555		lockPath, err := coordinationPath(path)
1556		if err != nil {
1557			return nil, nil, err
1558		}
1559		if err := os.MkdirAll(filepath.Dir(lockPath), 0o755); err != nil {
1560			return nil, nil, fmt.Errorf("准备协调文件失败: %w", err)
1561		}
1562		lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
1563		if err != nil {
1564			return nil, nil, fmt.Errorf("打开协调文件失败: %w", err)
1565		}
1566		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX); err != nil {
1567			_ = lock.Close()
1568			return nil, nil, fmt.Errorf("等待台账协调锁失败: %w", err)
1569		}
1570		release = func() {
1571			_ = syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
1572			_ = lock.Close()
1573		}
1574		s, err = Open(path)
1575		if err != nil {
1576			release()
1577			return nil, nil, err
1578		}
1579		return s, release, nil
1580	}
