1582	// Register 执行单件收件登记并将结果整体落盘。
1583	func (s *Store) Register(id, station string, now time.Time) (*Parcel, error) {
1584		if _, ok := s.data.Parcels[id]; ok {
1585			return nil, fmt.Errorf("包裹编号 %q 已登记，不能重复登记", id)
1586		}
1587		p := &Parcel{
1588			ID:         id,
1589			Station:    station,
1590			Status:     statusInStation,
1591			Registered: now,
1592			Trail: []Event{{
1593				Op:      "收件",
1594				Station: station,
1595				Time:    now,
1596			}},
1597		}
1598		s.data.Parcels[id] = p
1599		if err := s.save(); err != nil {
1600			delete(s.data.Parcels, id) // 落盘失败：回滚内存变更，保留原有有效数据
1601			return nil, err
1602		}
1603		return p, nil
1604	}
