1627	// Handoff 提交一次多件包裹的站点交接。
1628	//
1629	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
1630	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
1631	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
1632	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
1633	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
1634		if saved, ok := s.data.Handoffs[request]; ok {
1635			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
1636				return saved, true, nil
1637			}
1638			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
1639		}
1640	
1641		// 首次提交：先做全部校验，任何一件不满足都整体失败。
1642		for _, id := range parcels {
1643			p, ok := s.data.Parcels[id]
1644			if !ok {
1645				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
1646			}
1647			if p.Station != from {
1648				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
1649			}
1650			if inc := activeFreeze(p); inc != "" {
1651				return nil, false, fmt.Errorf("交接失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批交接拒绝，整次交接未执行", id, inc)
1652			}
1653			if p.Status != statusInStation {
1654				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前状态为 %q，不是在站，整次交接未执行", id, p.Status)
1655			}
1656		}
1657	
1658		res := &HandoffResult{
1659			Request: request,
1660			From:    from,
1661			To:      to,
1662			Parcels: append([]string(nil), parcels...),
1663			Time:    now,
1664		}
1665		s.data.Handoffs[request] = res
1666	
1667		// 记录旧值，落盘失败时整体回滚。
1668		prev := make(map[string]struct {
1669			station string
1670			trail   []Event
1671		}, len(parcels))
1672		for _, id := range parcels {
1673			p := s.data.Parcels[id]
1674			prev[id] = struct {
1675				station string
1676				trail   []Event
1677			}{p.Station, append([]Event(nil), p.Trail...)}
1678			p.Station = to
1679			p.Status = statusInStation
1680			p.Trail = append(p.Trail, Event{
1681				Op:      "交接",
1682				Station: to,
1683				Request: request,
1684				Time:    now,
1685			})
1686		}
1687	
1688		if err := s.save(); err != nil {
1689			delete(s.data.Handoffs, request)
1690			for id, old := range prev {
1691				p := s.data.Parcels[id]
1692				p.Station = old.station
1693				p.Trail = old.trail
1694			}
1695			return nil, false, err
1696		}
1697		return res, false, nil
1698	}
