1700	// Return 按原交接整批退回：实物送回该交接的源站点，批次与站点取自原交接结果。
1701	//
1702	// 首次退回：原交接必须存在且尚未成功退回；批次中每件包裹必须仍归属原交接目的站、
1703	// 状态为在站，且最后一条流转记录就是该原交接（请求重放不产生新流转，不影响判定）。
1704	// 任一条件不满足则整批拒绝，不作任何改动。全部满足时整批改归原交接源站（仍为在站），
1705	// 每件按批次顺序追加一条退回记录，原收件、交接轨迹保留不变。
1706	// 相同退回请求号且原交接、原因相同：直接返回首次结果，replayed 为 true，
1707	// 即使包裹之后又被交接也不重新检查；请求号相同但原交接或原因不同：报冲突。
1708	// 退回请求号与交接请求号分属独立去重范围，互不影响；失败的首次退回不占用请求号。
1709	func (s *Store) Return(request, handoffReq, reason string, now time.Time) (result *ReturnResult, replayed bool, err error) {
1710		if saved, ok := s.data.Returns[request]; ok {
1711			if saved.Handoff == handoffReq && saved.Reason == reason {
1712				return saved, true, nil
1713			}
1714			return nil, false, fmt.Errorf("退回请求号 %q 已用于一次不同的退回（原交接=%q 原因=%q），内容冲突",
1715				request, saved.Handoff, saved.Reason)
1716		}
1717	
1718		h, ok := s.data.Handoffs[handoffReq]
1719		if !ok {
1720			return nil, false, fmt.Errorf("退回失败：原交接请求号 %q 不存在", handoffReq)
1721		}
1722		if h.ReturnedBy != "" {
1723			return nil, false, fmt.Errorf("退回失败：原交接 %q 已成功退回（退回请求号 %q），不能再次退回", handoffReq, h.ReturnedBy)
1724		}
1725	
1726		// 先做全部校验，任何一件不满足都整批拒绝。
1727		for _, id := range h.Parcels {
1728			p, ok := s.data.Parcels[id]
1729			if !ok {
1730				return nil, false, fmt.Errorf("退回失败：包裹 %q 未登记，整批退回未执行", id)
1731			}
1732			if inc := activeFreeze(p); inc != "" {
1733				return nil, false, fmt.Errorf("退回失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批退回拒绝，整批退回未执行", id, inc)
1734			}
1735			if p.Station != h.To || p.Status != statusInStation {
1736				return nil, false, fmt.Errorf("退回失败：包裹 %q 当前归属 %q、状态 %q，不在原交接目的站 %q 在站，整批退回未执行",
1737					id, p.Station, p.Status, h.To)
1738			}
1739			last := lastFlowEvent(p.Trail)
1740			if last.Op != "交接" || last.Request != handoffReq {
1741				return nil, false, fmt.Errorf("退回失败：包裹 %q 在原交接 %q 之后又有新的流转，不能退回该交接，整批退回未执行",
1742					id, handoffReq)
1743			}
1744		}
1745	
1746		res := &ReturnResult{
1747			Request: request,
1748			Handoff: handoffReq,
1749			From:    h.To,
1750			To:      h.From,
1751			Reason:  reason,
1752			Parcels: append([]string(nil), h.Parcels...),
1753			Time:    now,
1754		}
1755		s.data.Returns[request] = res
1756		h.ReturnedBy = request
1757	
1758		// 记录旧值，落盘失败时整体回滚。
1759		prev := make(map[string]struct {
1760			station string
1761			trail   []Event
1762		}, len(h.Parcels))
1763		for _, id := range h.Parcels {
1764			p := s.data.Parcels[id]
1765			prev[id] = struct {
1766				station string
1767				trail   []Event
1768			}{p.Station, append([]Event(nil), p.Trail...)}
1769			p.Station = h.From
1770			p.Status = statusInStation
1771			p.Trail = append(p.Trail, Event{
1772				Op:         "退回",
1773				Station:    h.From,
1774				From:       h.To,
1775				Request:    request,
1776				RefRequest: handoffReq,
1777				Reason:     reason,
1778				Time:       now,
1779			})
1780		}
1781	
1782		if err := s.save(); err != nil {
1783			delete(s.data.Returns, request)
1784			h.ReturnedBy = ""
1785			for id, old := range prev {
1786				p := s.data.Parcels[id]
1787				p.Station = old.station
1788				p.Trail = old.trail
1789			}
1790			return nil, false, err
1791		}
1792		return res, false, nil
1793	}
