1795	// Dispatch 提交一次配送批次出站。
1796	//
1797	// 首次出站：所有包裹必须已登记、当前归属出发站且状态为在站，否则整批拒绝、不作任何改动；
1798	// 全部满足时整批转为“配送中”（站点仍记出发站），每件追加一条含批次、配送员和时间的
1799	// 出站记录，批次成员按首次提交顺序保存且不可修改。批次号标识一次配送，完成后也不能复用：
1800	// 相同批次号且站点、配送员、包裹集合（与顺序无关）相同，直接返回首次结果，replayed 为 true；
1801	// 批次号相同但内容不同报冲突；失败的首次出站不占用批次号。
1802	func (s *Store) Dispatch(batch, station, courier string, parcels []string, now time.Time) (result *BatchResult, replayed bool, err error) {
1803		if saved, ok := s.data.Batches[batch]; ok {
1804			if saved.RelayedFrom != "" {
1805				return nil, false, fmt.Errorf("批次号 %q 已由续接 %q 创建（来源批次 %q），不能用于出站，内容冲突",
1806					batch, saved.RelayRequest, saved.RelayedFrom)
1807			}
1808			if saved.Station == station && saved.Courier == courier && sameSet(saved.Parcels, parcels) {
1809				return saved, true, nil
1810			}
1811			return nil, false, fmt.Errorf("批次号 %q 已用于一次不同的出站（出发站=%q 配送员=%q），内容冲突", batch, saved.Station, saved.Courier)
1812		}
1813	
1814		// 首次出站：先做全部校验，任何一件不满足都整批拒绝。
1815		for _, id := range parcels {
1816			p, ok := s.data.Parcels[id]
1817			if !ok {
1818				return nil, false, fmt.Errorf("出站失败：包裹 %q 未登记，整批出站未执行", id)
1819			}
1820			if p.Station != station {
1821				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前归属 %q，不在出发站 %q，整批出站未执行", id, p.Station, station)
1822			}
1823			if inc := activeFreeze(p); inc != "" {
1824				return nil, false, fmt.Errorf("出站失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批出站拒绝，整批出站未执行", id, inc)
1825			}
1826			if p.Status != statusInStation {
1827				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前状态为 %q，不是在站，整批出站未执行", id, p.Status)
1828			}
1829		}
1830	
1831		res := &BatchResult{
1832			Batch:    batch,
1833			Station:  station,
1834			Courier:  courier,
1835			Parcels:  append([]string(nil), parcels...),
1836			Time:     now,
1837			Receipts: map[string]*ReceiptEntry{},
1838		}
1839		s.data.Batches[batch] = res
1840	
1841		// 记录旧值，落盘失败时整体回滚。
1842		prev := make(map[string]struct {
1843			status string
1844			trail  []Event
1845		}, len(parcels))
1846		for _, id := range parcels {
1847			p := s.data.Parcels[id]
1848			prev[id] = struct {
1849				status string
1850				trail  []Event
1851			}{p.Status, append([]Event(nil), p.Trail...)}
1852			p.Status = statusDelivering // 站点不变，仍记出发站
1853			p.Trail = append(p.Trail, Event{
1854				Op:      "出站",
1855				Station: station,
1856				Batch:   batch,
1857				Courier: courier,
1858				Time:    now,
1859			})
1860		}
1861	
1862		if err := s.save(); err != nil {
1863			delete(s.data.Batches, batch)
1864			for id, old := range prev {
1865				p := s.data.Parcels[id]
1866				p.Status = old.status
1867				p.Trail = old.trail
1868			}
1869			return nil, false, err
1870		}
1871		return res, false, nil
1872	}
