2309		}
2310		if p.Station != station {
2311			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前归属 %q，不在指定站点 %q，冻结未执行", parcel, p.Station, station)
2312		}
2313		if p.Status != statusInStation {
2314			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前状态为 %q，仅在站包裹可以冻结，冻结未执行", parcel, p.Status)
2315		}
2316	
2317		res = &FreezeResult{
2318			Incident: incident,
2319			Parcel:   parcel,
2320			Station:  station,
2321			Reason:   reason,
2322			Time:     now,
2323		}
2324		s.data.Freezes[incident] = res
2325	
2326		// 记录旧值，落盘失败时整体回滚。
2327		oldStatus := p.Status
2328		oldTrail := append([]Event(nil), p.Trail...)
2329		p.Status = statusFrozen // 站点不变
2330		p.Trail = append(p.Trail, Event{
2331			Op:       "冻结",
2332			Station:  station,
2333			Incident: incident,
2334			Reason:   reason,
2335			Time:     now,
2336		})
2337	
2338		if err := s.save(); err != nil {
2339			delete(s.data.Freezes, incident)
2340			p.Status, p.Trail = oldStatus, oldTrail
2341			return nil, false, err
2342		}
2343		return res, false, nil
2344	}
