2346	// Unfreeze 解除一件包裹当前的异常冻结。
2347	//
2348	// 首次解除：异常单必须存在且尚未解除，并且仍是该包裹当前冻结对应的异常单；
2349	// 异常单不存在、已解除或对应关系不符均拒绝。成功后包裹在原站恢复在站，原异常单
2350	// 永久标记为已解除（异常单号不得复用），追加一条含异常单号、解除请求号、处理说明及
2351	// 时间的解除记录，原冻结记录不删改；之后可用新异常单再次冻结。
2352	// 解除只是管理记录，不移动实物、不算新流转。
2353	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名：相同解除请求号且异常单、
2354	// 处理说明相同，直接返回首次解除结果与时间，replayed 为 true，不检查当前状态，也不影响
2355	// 后来新建的异常单或后续流转；请求号相同但内容不同报冲突；失败的首次解除不占用请求号。
2356	func (s *Store) Unfreeze(request, incident, note string, now time.Time) (res *UnfreezeResult, replayed bool, err error) {
2357		if saved, ok := s.data.Unfreezes[request]; ok {
2358			if saved.Incident == incident && saved.Note == note {
2359				return saved, true, nil
2360			}
2361			return nil, false, fmt.Errorf("解除请求号 %q 已用于一次不同的解除（异常单=%q 处理说明=%q），内容冲突",
2362				request, saved.Incident, saved.Note)
2363		}
2364	
2365		f, ok := s.data.Freezes[incident]
2366		if !ok {
2367			return nil, false, fmt.Errorf("解除失败：异常单号 %q 不存在，解除未执行", incident)
2368		}
2369		if f.ReleasedBy != "" {
2370			return nil, false, fmt.Errorf("解除失败：异常单 %q 已解除（解除请求号 %q），不能重复解除", incident, f.ReleasedBy)
2371		}
2372		p, ok := s.data.Parcels[f.Parcel]
2373		if !ok {
2374			return nil, false, fmt.Errorf("解除失败：异常单 %q 对应的包裹 %q 不存在，解除未执行", incident, f.Parcel)
2375		}
2376		if p.Status != statusFrozen || activeFreeze(p) != incident {
2377			return nil, false, fmt.Errorf("解除失败：异常单 %q 不是包裹 %q 当前冻结对应的异常单（当前异常单 %q），解除未执行",
2378				incident, f.Parcel, activeFreeze(p))
2379		}
2380	
2381		res = &UnfreezeResult{
2382			Request:  request,
2383			Incident: incident,
2384			Parcel:   f.Parcel,
2385			Note:     note,
2386			Time:     now,
2387		}
2388		s.data.Unfreezes[request] = res
2389		f.ReleasedBy = request
2390	
2391		// 记录旧值，落盘失败时整体回滚。
2392		oldStatus := p.Status
2393		oldTrail := append([]Event(nil), p.Trail...)
2394		p.Status = statusInStation // 在原站恢复在站，站点不变
2395		p.Trail = append(p.Trail, Event{
2396			Op:       "解除冻结",
2397			Station:  f.Station,
2398			Incident: incident,
2399			Request:  request,
2400			Note:     note,
2401			Time:     now,
2402		})
2403	
2404		if err := s.save(); err != nil {
2405			delete(s.data.Unfreezes, request)
2406			f.ReleasedBy = ""
2407			p.Status, p.Trail = oldStatus, oldTrail
2408			return nil, false, err
2409		}
2410		return res, false, nil
2411	}
