2413	// Abort 中止一个配送批次：配送员已将该批次仍由本批次配送的全部待配送包裹实物
2414	// 收回出发站。成员与站点取自原批次结果，不允许另选成员或站点。
2415	//
2416	// 首次中止：批次必须存在、未中止、未永久转交，且至少有一件待配送成员（无有效
2417	// 回执且未在此前各次续接中转交）；这些成员必须仍在原批次配送中、归属出发站，
2418	// 任一不符整批拒绝、不作任何改动。已回执成员与已转交成员不检查也不变更，其后续
2419	// 流转或冻结不阻止中止。全部满足时按原成员顺序将全部待配送件恢复“在站”
2420	// （站点为出发站），各追加一条含批次、中止请求号、原因、站点和时间的收回记录；
2421	// 收回不是失败回执，批次回执记录与转交记录不变。中止永久关闭原批次，原成员顺序、
2422	// 配送员与出站时间保留不变。
2423	// 收回算新的流转，收回后不能退回出站前的旧交接；收回件可交接、冻结或再次出站，
2424	// 但不能首次回执旧批次（receipt 与 receipt-import 同样遵守）。
2425	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名：相同请求号且批次、
2426	// 清理后的原因相同，直接返回首次收回集合与时间，replayed 为 true，不重新计算成员、
2427	// 不检查当前状态、不改写台账；请求号相同但批次或原因不同报冲突。
2428	// 每批只能成功中止一次：换请求号再中止、中止已完成或已永久转交的批次均拒绝；
2429	// 失败的首次中止不占用请求号。
2430	func (s *Store) Abort(request, batch, reason string, now time.Time) (res *AbortResult, replayed bool, err error) {
2431		if saved, ok := s.data.Aborts[request]; ok {
2432			if saved.Batch == batch && saved.Reason == reason {
2433				return saved, true, nil
2434			}
2435			return nil, false, fmt.Errorf("中止请求号 %q 已用于一次不同的中止（批次=%q 原因=%q），内容冲突",
2436				request, saved.Batch, saved.Reason)
2437		}
2438	
2439		b, ok := s.data.Batches[batch]
2440		if !ok {
2441			return nil, false, fmt.Errorf("中止失败：批次号 %q 不存在", batch)
2442		}
2443		if b.AbortedBy != "" {
2444			return nil, false, fmt.Errorf("中止失败：批次 %q 已中止（中止请求号 %q），每批只能成功中止一次", batch, b.AbortedBy)
2445		}
2446		if b.TransferredBy != "" {
2447			return nil, false, fmt.Errorf("中止失败：批次 %q 已永久转交（续接请求号 %q），不能中止", batch, b.TransferredBy)
2448		}
2449	
2450		// 按原成员顺序挑出仍由本批次配送的待配送成员（无有效回执且未转交）。
2451		recalled := b.openParcels(&s.data)
2452		if len(recalled) == 0 {
2453			return nil, false, fmt.Errorf("中止失败：批次 %q 没有待配送成员，不能中止", batch)
2454		}
2455	
2456		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
2457		for _, pid := range recalled {
2458			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
2459			if p.Status != statusDelivering || currentBatch(p) != batch || p.Station != b.Station {
2460				return nil, false, fmt.Errorf("中止失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批中止未执行",
2461					pid, p.Station, p.Status, batch, b.Station)
2462			}
2463		}
2464	
2465		res = &AbortResult{
2466			Request: request,
2467			Batch:   batch,
2468			Station: b.Station,
2469			Reason:  reason,
2470			Parcels: recalled,
2471			Time:    now,
2472		}
2473		s.data.Aborts[request] = res
2474		b.AbortedBy = request
2475	
2476		// 记录旧值，落盘失败时整体回滚。
2477		prev := make(map[string]struct {
2478			status string
2479			trail  []Event
2480		}, len(recalled))
2481		for _, pid := range recalled {
2482			p := s.data.Parcels[pid]
2483			prev[pid] = struct {
2484				status string
2485				trail  []Event
2486			}{p.Status, append([]Event(nil), p.Trail...)}
2487			p.Status = statusInStation // 实物已收回出发站，站点仍记出发站
2488			p.Trail = append(p.Trail, Event{
2489				Op:      "收回",
2490				Station: b.Station,
2491				Batch:   batch,
2492				Request: request,
2493				Reason:  reason,
2494				Time:    now,
2495			})
2496		}
2497	
2498		if err := s.save(); err != nil {
2499			delete(s.data.Aborts, request)
2500			b.AbortedBy = ""
2501			for pid, old := range prev {
2502				p := s.data.Parcels[pid]
2503				p.Status = old.status
2504				p.Trail = old.trail
2505			}
2506			return nil, false, err
2507		}
2508		return res, false, nil
2509	}
