2511	// BatchAbort 返回一个配送批次的中止结果；批次不存在或未中止时返回 nil。
2512	func (s *Store) BatchAbort(batch string) *AbortResult {
2513		b, ok := s.data.Batches[batch]
2514		if !ok || b.AbortedBy == "" {
2515			return nil
2516		}
2517		return s.data.Aborts[b.AbortedBy]
2518	}
