2520	// Transfer 在配送途中把原批次的部分或全部待配送包裹交给另一配送员，新建批次
2521	// 继续配送，无需回站。站点取自原批次，不可另选；成员可两种方式选择：parcels
2522	// 为 nil 表示不选成员，取当时全部无有效回执且未转交的待配送件；非 nil 为显式
2523	// 选择的非空、不重复集合（由调用方清洗）。
2524	//
2525	// 首次续接：原批次必须存在、未中止、未永久转交；新批次号必须从未被出站或续接
2526	// 使用；新配送员必须与原配送员不同。显式集合的每件选中件都必须属于原批次、
2527	// 无有效回执且未转交，并仍在该批次由出发站配送中；不选成员时本次集合为当时全部
2528	// 待配送件（它们同样必须仍在原批次配送中）。任一不符整次拒绝、不作任何改动。
2529	// 已有有效回执或已转交的成员不检查也不变更，其后续流转或冻结不阻止续接。
2530	// 成功时按原成员顺序以选中件创建新批次，沿用出发站，记录新配送员及接手时间；
2531	// 选中件保持“配送中”及原站点，当前配送归属切换到新批次，各追加一条含请求号、
2532	// 前后批次、新配送员、站点、原因和时间的续接记录；未选余件不变。原成员、配送员、
2533	// 出站时间与已有回执保留。原批次可多次分批续接：仍有待配送件时保持配送中；
2534	// 余件经回执办结时已完成（可按原条件撤销恢复配送）；续接转走最后一件待配送件时
2535	// 原批次才永久关闭为“已转交”。转交不算回执、收回或再次出站。续接算新的流转，
2536	// 续接后不能退回配送前的旧交接。
2537	// 两种选择方式共用续接请求号去重范围，可与批次号、包裹号及其他业务编号同名：
2538	// 相同请求号且原批次、新批次、新配送员、清理后的原因、选择方式相同（显式集合
2539	// 换序无关），直接返回首次转交集合、续接信息及时间，replayed 为 true，不检查
2540	// 现状、不重算余件、不追加轨迹、不改写台账（后续回执、中止或再次续接后仍成立）；
2541	// 请求号相同但内容或选择方式不同报冲突；失败的首次续接不占用请求号。
2542	func (s *Store) Transfer(request, fromBatch, toBatch, courier, reason string, parcels []string, now time.Time) (res *TransferResult, replayed bool, err error) {
2543		explicit := parcels != nil
2544		if saved, ok := s.data.Transfers[request]; ok {
2545			if saved.FromBatch == fromBatch && saved.ToBatch == toBatch && saved.ToCourier == courier &&
2546				saved.Reason == reason && saved.Explicit == explicit &&
2547				(!explicit || sameSet(saved.Parcels, parcels)) {
2548				return saved, true, nil
2549			}
2550			return nil, false, fmt.Errorf("续接请求号 %q 已用于一次不同的续接（原批次=%q 新批次=%q 新配送员=%q），内容冲突",
2551				request, saved.FromBatch, saved.ToBatch, saved.ToCourier)
2552		}
2553	
2554		b, ok := s.data.Batches[fromBatch]
2555		if !ok {
2556			return nil, false, fmt.Errorf("续接失败：原批次号 %q 不存在", fromBatch)
2557		}
2558		if b.AbortedBy != "" {
2559			return nil, false, fmt.Errorf("续接失败：批次 %q 已中止（中止请求号 %q），不能续接", fromBatch, b.AbortedBy)
2560		}
2561		if b.TransferredBy != "" {
2562			return nil, false, fmt.Errorf("续接失败：批次 %q 已永久转交（续接请求号 %q），不能再次续接", fromBatch, b.TransferredBy)
2563		}
2564		if _, used := s.data.Batches[toBatch]; used {
2565			return nil, false, fmt.Errorf("续接失败：新批次号 %q 已被出站或续接使用，不能复用", toBatch)
2566		}
2567		if courier == b.Courier {
2568			return nil, false, fmt.Errorf("续接失败：新配送员 %q 不能与原批次 %q 的配送员相同", courier, fromBatch)
2569		}
2570	
2571		// 本次集合：显式方式校验指定集合，不选方式取当时全部待配送件；均按原成员顺序。
2572		open := b.openParcels(&s.data)
2573		openSet := make(map[string]bool, len(open))
2574		for _, pid := range open {
2575			openSet[pid] = true
2576		}
2577		var moved []string
2578		if explicit {
2579			if len(parcels) == 0 {
2580				return nil, false, fmt.Errorf("续接失败：显式选择的包裹集合不可为空，整次续接未执行")
2581			}
2582			want := make(map[string]bool, len(parcels))
2583			for _, pid := range parcels {
2584				if want[pid] {
2585					return nil, false, fmt.Errorf("续接失败：显式集合中包裹 %q 重复，整次续接未执行", pid)
2586				}
2587				want[pid] = true
2588				if !openSet[pid] {
2589					// 区分不属于批次、已有有效回执/已转交等情形，给出明确原因。
2590					member := false
2591					for _, mid := range b.Parcels {
2592						if mid == pid {
2593							member = true
2594							break
2595						}
2596					}
2597					if !member {
2598						return nil, false, fmt.Errorf("续接失败：包裹 %q 不属于原批次 %q，整次续接未执行", pid, fromBatch)
2599					}
2600					return nil, false, fmt.Errorf("续接失败：包裹 %q 在批次 %q 已有有效回执或已转交，不能再次选中，整次续接未执行", pid, fromBatch)
2601				}
2602			}
2603			for _, pid := range b.Parcels {
2604				if want[pid] {
2605					moved = append(moved, pid)
2606				}
2607			}
2608		} else {
2609			moved = append(moved, open...)
2610			if len(moved) == 0 {
2611				return nil, false, fmt.Errorf("续接失败：批次 %q 没有待配送成员，不能续接", fromBatch)
2612			}
2613		}
2614	
2615		// 先做全部校验：选中件必须仍在原批次由出发站配送中，任一不符整次拒绝。
2616		for _, pid := range moved {
2617			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
2618			if p.Status != statusDelivering || currentBatch(p) != fromBatch || p.Station != b.Station {
2619				return nil, false, fmt.Errorf("续接失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整次续接未执行",
2620					pid, p.Station, p.Status, fromBatch, b.Station)
2621			}
2622		}
2623	
2624		res = &TransferResult{
2625			Request:     request,
2626			FromBatch:   fromBatch,
2627			ToBatch:     toBatch,
2628			Station:     b.Station,
2629			FromCourier: b.Courier,
2630			ToCourier:   courier,
2631			Reason:      reason,
2632			Parcels:     append([]string(nil), moved...),
2633			Time:        now,
2634			Explicit:    explicit,
2635		}
2636		s.data.Transfers[request] = res
2637		s.data.Batches[toBatch] = &BatchResult{
2638			Batch:        toBatch,
2639			Station:      b.Station,
2640			Courier:      courier,
2641			Parcels:      append([]string(nil), moved...),
2642			Time:         now,
2643			Receipts:     map[string]*ReceiptEntry{},
2644			RelayedFrom:  fromBatch,
2645			RelayRequest: request,
2646		}
2647		b.Transfers = append(b.Transfers, request)
2648		// 转走最后一件待配送件：原批次永久关闭为“已转交”；有余件则保持配送中。
2649		if len(b.openParcels(&s.data)) == 0 {
2650			b.TransferredBy = request
2651		}
2652	
2653		// 记录旧值，落盘失败时整体回滚。包裹保持“配送中”及原站点，只追加续接轨迹。
2654		prev := make(map[string][]Event, len(moved))
2655		for _, pid := range moved {
2656			p := s.data.Parcels[pid]
2657			prev[pid] = append([]Event(nil), p.Trail...)
2658			p.Trail = append(p.Trail, Event{
2659				Op:        "续接",
2660				Station:   b.Station,
2661				Batch:     toBatch,
2662				FromBatch: fromBatch,
2663				Courier:   courier,
2664				Request:   request,
2665				Reason:    reason,
2666				Time:      now,
2667			})
2668		}
2669	
2670		if err := s.save(); err != nil {
2671			delete(s.data.Transfers, request)
2672			delete(s.data.Batches, toBatch)
2673			b.Transfers = b.Transfers[:len(b.Transfers)-1]
2674			b.TransferredBy = ""
2675			for pid, old := range prev {
2676				s.data.Parcels[pid].Trail = old
2677			}
2678			return nil, false, err
2679		}
2680		return res, false, nil
2681	}
