2948	// Reroute 提交一次运输途中改址：将一张运输单当前全部未收件改送另一目的站，
2949	// 不另建运输单、不重新发运。成员取自受理时的全部未收件，不允许另选。
2950	//
2951	// 首次受理：运输单必须存在且仍有未收件；预期当前目的站必须等于当前有效目的站
2952	// （原目的站应用已有各次改址后）；新目的站必须不同于当前有效目的站和源站。
2953	// 本次集合为受理时的全部未收件，每件都必须仍归该单在源站站间在途，任一不符
2954	// 整次拒绝、不作任何改动。已收件不参与受理条件检查也不变更，其后续合法作业
2955	// 不阻止改址。成功时按原发运顺序保存本次集合，成员仍归源站、保持站间在途及
2956	// 作业限制，只变更余件的有效目的站，逐件追加一条含请求号、运输单、前后目的站、
2957	// 原因和时间的改址轨迹；原成员、发运结果、已有接收事实与轨迹永久保留。
2958	// 改址可发生在发运与接收之间，允许再次改址（每次以当时余件为准），全部接收后
2959	// 拒绝新改址；改址不算到站、不恢复旧交接退回资格。
2960	// 改址请求号独立去重，可与运输单号及其他业务编号同名：相同请求号且运输单、
2961	// 预期当前目的站、新目的站、清理后的原因相同，直接返回首次改址信息、集合与
2962	// 时间，replayed 为 true，不检查现状、不重算余件、不改写台账（再次改址、接收
2963	// 和后续流转后仍成立）；请求号相同但内容不同报冲突；失败的首次改址不占用请求号。
2964	func (s *Store) Reroute(request, shipment, expect, to, reason string, now time.Time) (res *RerouteResult, replayed bool, err error) {
2965		if saved, ok := s.data.Reroutes[request]; ok {
2966			if saved.Shipment == shipment && saved.From == expect && saved.To == to && saved.Reason == reason {
2967				return saved, true, nil
2968			}
2969			return nil, false, fmt.Errorf("改址请求号 %q 已用于一次不同的改址（运输单=%q 新目的站=%q），内容冲突",
2970				request, saved.Shipment, saved.To)
2971		}
2972	
2973		sh, ok := s.data.Shipments[shipment]
2974		if !ok {
2975			return nil, false, fmt.Errorf("改址失败：运输单号 %q 不存在", shipment)
2976		}
2977		cur := s.effectiveTo(sh)
2978		if expect != cur {
2979			return nil, false, fmt.Errorf("改址失败：预期当前目的站 %q 与运输单 %q 当前有效目的站 %q 不符，整次改址未执行",
2980				expect, shipment, cur)
2981		}
2982		if to == cur {
2983			return nil, false, fmt.Errorf("改址失败：新目的站 %q 不能与当前有效目的站相同，整次改址未执行", to)
2984		}
2985		if to == sh.From {
2986			return nil, false, fmt.Errorf("改址失败：新目的站 %q 不能与运输单 %q 源站相同，整次改址未执行", to, shipment)
2987		}
2988	
2989		// 本次集合为受理时的全部未收件，按发运保存顺序。
2990		received := s.receivedUnder(shipment)
2991		members := make([]string, 0, len(sh.Parcels))
2992		for _, pid := range sh.Parcels {
2993			if !received[pid] {
2994				members = append(members, pid)
2995			}
2996		}
2997		if len(members) == 0 {
2998			return nil, false, fmt.Errorf("改址失败：运输单 %q 已全部接收（接收请求号 %q），没有未收件，不能改址", shipment, sh.ReceivedBy)
2999		}
3000	
3001		// 先做全部校验：每件未收件都必须仍归该单在源站站间在途，任一不符整次拒绝。
3002		for _, pid := range members {
3003			p := s.data.Parcels[pid] // 运输单成员必已登记（载入校验保证）
3004			if p.Status != statusInTransit || p.Station != sh.From {
3005				return nil, false, fmt.Errorf("改址失败：包裹 %q 当前归属 %q、状态 %q，不在运输单 %q 从源站 %q 在途，整次改址未执行",
3006					pid, p.Station, p.Status, shipment, sh.From)
3007			}
3008		}
3009	
3010		res = &RerouteResult{
3011			Request:  request,
3012			Shipment: shipment,
3013			From:     cur,
3014			To:       to,
3015			Reason:   reason,
3016			Parcels:  members,
3017			Time:     now,
3018		}
3019		s.data.Reroutes[request] = res
3020		sh.Reroutes = append(sh.Reroutes, request)
3021	
3022		// 记录旧值，落盘失败时整体回滚。包裹仍归源站、保持站间在途，只追加改址轨迹。
3023		prev := make(map[string][]Event, len(members))
3024		for _, pid := range members {
3025			p := s.data.Parcels[pid]
3026			prev[pid] = append([]Event(nil), p.Trail...)
3027			p.Trail = append(p.Trail, Event{
3028				Op:       "改址",
3029				Station:  sh.From,
3030				From:     cur,
3031				To:       to,
3032				Shipment: shipment,
3033				Request:  request,
3034				Reason:   reason,
3035				Time:     now,
3036			})
3037		}
3038	
3039		if err := s.save(); err != nil {
3040			delete(s.data.Reroutes, request)
3041			sh.Reroutes = sh.Reroutes[:len(sh.Reroutes)-1]
3042			for pid, old := range prev {
3043				s.data.Parcels[pid].Trail = old
3044			}
3045			return nil, false, err
3046		}
3047		return res, false, nil
3048	}
