192		request := fs.String("request", "", "交接请求号（用于去重）")
193		from := fs.String("from", "", "源站点")
194		to := fs.String("to", "", "目的站点")
195		var parcels stringList
196		fs.Var(&parcels, "parcel", "包裹编号，可重复指定；集合不可为空或含重复编号")
197		if ok, code := parseFlags(fs, argv, stdout, stderr, printHandoffHelp); !ok {
