212		if err != nil {
213			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
214			return exitBusiness
215		}
216		if len(parcels) == 0 {
217			fmt.Fprintf(stderr, "%s handoff: 包裹集合不可为空，至少需要一个 --parcel\n", appName)
218			return exitBusiness
219		}
220		cleanParcels := make([]string, 0, len(parcels))
221		seen := make(map[string]bool, len(parcels))
222		for _, raw := range parcels {
223			id, err := cleanID("包裹编号", raw)
224			if err != nil {
225				fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
226				return exitBusiness
227			}
228			if seen[id] {
229				fmt.Fprintf(stderr, "%s handoff: 包裹集合中编号 %q 重复\n", appName, id)
230				return exitBusiness
231			}
232			seen[id] = true
233			cleanParcels = append(cleanParcels, id)
234		}
235		if cleanFrom == cleanTo {
236			fmt.Fprintf(stderr, "%s handoff: 源站点与目的站点不能相同（均为 %q）\n", appName, cleanFrom)
