473	// receiptFileRecord 是回执整批导入文件中的单条记录（JSON）。
474	type receiptFileRecord struct {
475		Request string `json:"request"`
476		Batch   string `json:"batch"`
477		Parcel  string `json:"parcel"`
478		Result  string `json:"result"`
479		Reason  string `json:"reason"`
480	}
481	
482	// loadReceiptImportFile 读取并解析回执整批导入文件。文件为有序且非空的
483	// JSON 数组，元素为 request/batch/parcel/result/reason 字段的对象；
484	// 文件只读，绝不改写。任一记录清洗后不合法或请求号在文件内重复，
485	// 都返回带记录位置的错误，整份不予导入。
486	func loadReceiptImportFile(path string) ([]ReceiptImportRecord, error) {
487		raw, err := os.ReadFile(path)
488		if err != nil {
489			return nil, fmt.Errorf("读取回执导入文件失败: %w", err)
490		}
491		dec := json.NewDecoder(bytes.NewReader(raw))
492		dec.DisallowUnknownFields()
493		var records []receiptFileRecord
494		if err := dec.Decode(&records); err != nil {
495			return nil, fmt.Errorf("解析回执导入文件失败: %w", err)
496		}
497		var extra any
498		if err := dec.Decode(&extra); err != io.EOF {
499			return nil, fmt.Errorf("解析回执导入文件失败: 回执列表之后存在多余内容")
500		}
501		if len(records) == 0 {
502			return nil, fmt.Errorf("回执导入文件必须是有序且非空的回执列表")
503		}
504	
505		clean := make([]ReceiptImportRecord, 0, len(records))
506		seen := make(map[string]bool, len(records))
507		for i, rawRec := range records {
508			rec, err := cleanReceiptImportRecord(rawRec)
509			if err != nil {
510				return nil, fmt.Errorf("第 %d 条记录: %w", i+1, err)
511			}
512			if seen[rec.Request] {
513				return nil, fmt.Errorf("第 %d 条记录: 回执请求号 %q 在文件内重复", i+1, rec.Request)
514			}
515			seen[rec.Request] = true
516			clean = append(clean, rec)
517		}
518		return clean, nil
519	}
520	
521	// cleanReceiptImportRecord 清洗并校验一条导入记录：各标识去除两端空白后不可为空；
522	// 结果为失败时必须给出清理后非空的原因，签收时不可带原因。
523	func cleanReceiptImportRecord(raw receiptFileRecord) (ReceiptImportRecord, error) {
524		var rec ReceiptImportRecord
525		var err error
526		if rec.Request, err = cleanID("回执请求号", raw.Request); err != nil {
527			return rec, err
528		}
529		if rec.Batch, err = cleanID("批次号", raw.Batch); err != nil {
530			return rec, err
531		}
532		if rec.Parcel, err = cleanID("包裹编号", raw.Parcel); err != nil {
533			return rec, err
534		}
535		if rec.Result, err = cleanID("回执结果", raw.Result); err != nil {
536			return rec, err
537		}
538		if rec.Result != resultSigned && rec.Result != resultFailed {
539			return rec, fmt.Errorf("回执结果只能是 %q 或 %q，得到 %q", resultSigned, resultFailed, rec.Result)
540		}
541		rec.Reason = strings.TrimSpace(raw.Reason)
542		if rec.Result == resultFailed && rec.Reason == "" {
543			return rec, fmt.Errorf("结果为失败时原因不可为空或仅含空白")
544		}
545		if rec.Result == resultSigned && rec.Reason != "" {
546			return rec, fmt.Errorf("结果为签收时不可带原因")
547		}
548		return rec, nil
549	}
