12	// runParallel 从 n 个“终端”同时执行同一条命令（各自带不同的参数），
13	// 返回每次调用的 stdout、stderr 与退出码。各调用共享同一数据文件路径。
14	func runParallel(t *testing.T, n int, mkArgs func(i int) []string) (outs, errs []string, codes []int) {
15		t.Helper()
16		outs, errs, codes = make([]string, n), make([]string, n), make([]int, n)
17		start := make(chan struct{})
18		var wg sync.WaitGroup
19		for i := 0; i < n; i++ {
20			wg.Add(1)
21			go func(i int) {
22				defer wg.Done()
23				<-start
24				var out, errb strings.Builder
25				codes[i] = run(mkArgs(i), &out, &errb)
26				outs[i], errs[i] = out.String(), errb.String()
27			}(i)
28		}
29		close(start)
30		wg.Wait()
31		return outs, errs, codes
32	}
33	
34	func countCodes(codes []int, want int) int {
35		n := 0
36		for _, c := range codes {
37			if c == want {
38				n++
39			}
40		}
41		return n
42	}
