227	// 同一签收同时办理实物退件与撤销：竞争至多一方成功；另一方以状态码 1 退出
228	// 且不占用编号。反复多次以覆盖两种胜出顺序。
229	func TestConcurrentReceiptReturnVsRevoke(t *testing.T) {
230		for iter := 0; iter < 6; iter++ {
231			dbPath := filepath.Join(t.TempDir(), "ledger.json")
232			if _, _, code := runCLI(t, dbPath, "register", "--id", "P001", "--station", "站点A"); code != 0 {
233				t.Fatalf("登记失败")
234			}
235			if _, _, code := runCLI(t, dbPath, "dispatch", "--batch", "B1",
236				"--station", "站点A", "--courier", "张三", "--parcel", "P001"); code != 0 {
237				t.Fatalf("出站失败")
238			}
239			if _, _, code := runCLI(t, dbPath, "receipt", "--request", "RC1",
240				"--batch", "B1", "--parcel", "P001", "--result", "签收"); code != 0 {
241				t.Fatalf("签收失败")
242			}
243			_, errs, codes := runParallel(t, 2, func(i int) []string {
244				if i == 0 {
245					return []string{"--data", dbPath, "receipt-return", "--request", "RR1",
246						"--receipt", "RC1", "--reason", "客户退货"}
247				}
248				return []string{"--data", dbPath, "receipt-revoke", "--request", "RV1",
249					"--receipt", "RC1", "--reason", "误录签收"}
250			})
251			if got := countCodes(codes, exitOK); got != 1 {
252				t.Fatalf("第 %d 轮：退件与撤销应恰好一方成功，成功 %d 次（codes=%v errs=%v）", iter, got, codes, errs)
253			}
254	
255			s, err := Open(dbPath)
256			if err != nil {
257				t.Fatalf("打开台账失败: %v", err)
258			}
259			p, _ := s.Query("P001")
260			switch {
261			case codes[0] == exitOK:
262				// 退件胜出：包裹在站、末条退件轨迹；签收未撤销且标记退件；撤销号不占。
263				if p.Status != statusInStation || p.Station != "站点A" {
264					t.Fatalf("第 %d 轮：退件胜出后应在站: %+v", iter, p)
265				}
266				if p.Trail[len(p.Trail)-1].Op != "退件" {
267					t.Fatalf("第 %d 轮：退件胜出后末条应为退件: %+v", iter, p.Trail)
268				}
269				rc := s.ReceiptOf("RC1")
270				if rc.RevokedBy != "" || rc.ReturnedBy != "RR1" {
271					t.Fatalf("第 %d 轮：退件胜出后签收应标记退件未撤销: %+v", iter, rc)
272				}
273				if s.data.Revokes["RV1"] != nil {
274					t.Fatalf("第 %d 轮：失败的撤销不得占用 RV1", iter)
275				}
276				if _, _, err := s.RevokeReceipt("RV1", "RC1", "误录签收", tClock(2026, 10, 5, 12, 0)); err == nil {
277					t.Fatalf("第 %d 轮：退件胜出后再次撤销仍应拒绝", iter)
278				}
279			default:
280				// 撤销胜出：包裹配送中、末条撤销轨迹；退件号不占。
281				if p.Status != statusDelivering || p.Station != "站点A" {
282					t.Fatalf("第 %d 轮：撤销胜出后应恢复配送中: %+v", iter, p)
283				}
284				if p.Trail[len(p.Trail)-1].Op != "撤销回执" {
285					t.Fatalf("第 %d 轮：撤销胜出后末条应为撤销回执: %+v", iter, p.Trail)
286				}
287				rc := s.ReceiptOf("RC1")
288				if rc.ReturnedBy != "" || rc.RevokedBy != "RV1" {
289					t.Fatalf("第 %d 轮：撤销胜出后签收应标记撤销无退件: %+v", iter, rc)
290				}
291				if s.data.ReceiptReturns["RR1"] != nil {
292					t.Fatalf("第 %d 轮：失败的退件不得占用 RR1", iter)
293				}
294			}
295		}
296	}
