298	// 同一路径的相对、绝对及含 .、.. 的写法须归一到同一协调文件。
299	func TestCoordinationPathForms(t *testing.T) {
300		dir := t.TempDir()
301		base := filepath.Join(dir, "ledger.json")
302		forms := []string{
303			base,
304			filepath.Join(dir, ".", "ledger.json"),
305			filepath.Join(dir, "sub", "..", "ledger.json"),
306		}
307		var want string
308		for i, f := range forms {
309			got, err := coordinationPath(f)
310			if err != nil {
311				t.Fatalf("coordinationPath(%q) 失败: %v", f, err)
312			}
313			if i == 0 {
314				want = got
315				continue
316			}
317			if got != want {
318				t.Fatalf("路径写法 %q 的协调文件 %q 与 %q 不一致", f, got, want)
319			}
320		}
321	
322		// 相对路径与绝对路径也归一到同一把锁。
323		cwd, err := os.Getwd()
324		if err != nil {
325			t.Fatalf("获取工作目录失败: %v", err)
326		}
327		rel, err := filepath.Rel(cwd, base)
328		if err != nil {
329			t.Fatalf("计算相对路径失败: %v", err)
330		}
331		got, err := coordinationPath(rel)
332		if err != nil {
333			t.Fatalf("coordinationPath(%q) 失败: %v", rel, err)
334		}
335		if got != want {
336			t.Fatalf("相对路径 %q 的协调文件 %q 与绝对路径的 %q 不一致", rel, got, want)
337		}
