340	// 不同路径写法按同一台账协调：相对路径登记后，含 .、.. 的绝对写法
341	// 看到的仍是同一份台账（重复登记退出 1）。
342	func TestPathFormsShareLedger(t *testing.T) {
343		dir := t.TempDir()
344		t.Chdir(dir)
345		if _, _, code := runCLI(t, "ledger.json", "register", "--id", "P001", "--station", "站点A"); code != 0 {
346			t.Fatalf("相对路径登记失败")
347		}
