349		_, errText, code := runCLI(t, alt, "register", "--id", "P001", "--station", "站点B")
350		if code != exitBusiness || !strings.Contains(errText, "已登记") {
351			t.Fatalf("含 .、.. 的写法应识别为同一台账并拒绝重复登记: code=%d err=%s", code, errText)
352		}
