// 当前预留由状态为“待出站”的清单成员唯一推导（载入校验保证不重复预留）。
func (l *ledgerFile) activeReservation(id string) *SortManifest {
	for _, m := range l.Manifests {
		if m == nil || m.Status != manifestPending {
