	}
	fmt.Fprintf(stdout, "%s\n分拣清单号: %s\n批次号: %s\n出发站: %s\n配送员: %s\n包裹（%d 件）:\n",
		headline, res.Manifest, res.Batch, res.Station, res.Courier, len(res.Parcels))
