12	func mustManifest(t *testing.T, s *Store, manifest, station string, parcels []string, now time.Time) *SortManifest {
13		t.Helper()
14		res, replayed, err := s.CreateManifest(manifest, station, parcels, now)
15		if err != nil || replayed {
16			t.Fatalf("CreateManifest(%q) 意外失败: %v replayed=%v", manifest, err, replayed)
17		}
18		return res
19	}
20	
21	func manifestStore(t *testing.T) (*Store, string) {
22		t.Helper()
23		s, path := openTempStore(t)
24		now := tClock(2026, 10, 5, 9, 0)
25		mustRegister(t, s, "P001", "站点A", now)
26		mustRegister(t, s, "P002", "站点A", now)
27		mustRegister(t, s, "P003", "站点A", now)
28		return s, path
29	}
