31	// 创建清单：成员按首次顺序保存，站点、状态不变，逐件追加分拣预留管理记录。
32	func TestCreateManifestSuccess(t *testing.T) {
33		s, _ := manifestStore(t)
34		res := mustManifest(t, s, "M1", "站点A", []string{"P002", "P001"}, tClock(2026, 10, 5, 9, 30))
35	
36		if res.Status != manifestPending || res.Station != "站点A" ||
37			len(res.Parcels) != 2 || res.Parcels[0] != "P002" || res.Parcels[1] != "P001" {
38			t.Fatalf("清单结果不符: %+v", res)
39		}
40		for _, id := range []string{"P001", "P002"} {
41			p, _ := s.Query(id)
42			if p.Station != "站点A" || p.Status != statusInStation {
43				t.Fatalf("%s 预留后站点/状态应不变: %+v", id, p)
44			}
45			e := p.Trail[len(p.Trail)-1]
46			if e.Op != "分拣预留" || e.Manifest != "M1" || e.Station != "站点A" {
47				t.Fatalf("%s 末条应为分拣预留记录: %+v", id, e)
48			}
49			if s.ActiveManifest(id) == nil || s.ActiveManifest(id).Manifest != "M1" {
50				t.Fatalf("%s 应被清单 M1 预留", id)
51			}
52		}
53		if s.ActiveManifest("P003") != nil {
54			t.Fatal("P003 不应被预留")
55		}
56	}
57	
58	// 创建的整单校验：任一不符整单拒绝，不占清单号、不追加轨迹；失败不占号，纠正后同号可成功。
59	func TestCreateManifestRejectsAtomic(t *testing.T) {
60		s, path := manifestStore(t)
61		now := tClock(2026, 10, 5, 9, 0)
62		if _, err := s.Register("P004", "站点A", now); err != nil {
63			t.Fatal(err)
64		}
65		mustDispatch(t, s, "B1", "站点A", "张三", []string{"P003"}, tClock(2026, 10, 5, 9, 20))
66		mustManifest(t, s, "M1", "站点A", []string{"P002"}, tClock(2026, 10, 5, 9, 25))
67		mustHandoff(t, s, "H1", "站点A", "站点B", []string{"P001"}, tClock(2026, 10, 5, 9, 28))
68	
69		before, err := os.ReadFile(path)
70		if err != nil {
71			t.Fatal(err)
72		}
73		cases := []struct {
74			name    string
75			station string
76			parcels []string
77		}{
78			{"含未登记包裹", "站点A", []string{"P004", "GHOST"}},
79			{"含其他站点包裹", "站点A", []string{"P001"}},
80			{"含配送中包裹", "站点A", []string{"P003"}},
81			{"含已被其他清单预留的包裹", "站点A", []string{"P004", "P002"}},
82		}
83		for _, c := range cases {
84			trailBefore := len(s.data.Parcels["P004"].Trail)
85			if _, _, err := s.CreateManifest("MBAD", c.station, c.parcels, tClock(2026, 10, 5, 9, 40)); err == nil {
86				t.Fatalf("%s：应整单拒绝", c.name)
87			}
88			if s.data.Manifests["MBAD"] != nil {
89				t.Fatalf("%s：失败不得占用清单号 MBAD", c.name)
90			}
91			if got := len(s.data.Parcels["P004"].Trail); got != trailBefore {
92				t.Fatalf("%s：整单拒绝不得追加轨迹", c.name)
93			}
94		}
95		// 失败全部发生在锁内同一内存台账，未落盘；文件仍是最后一次成功（交接 H1）的内容。
96		after, err := os.ReadFile(path)
97		if err != nil {
98			t.Fatal(err)
99		}
100		if string(before) != string(after) {
101			t.Fatal("失败创建不得落盘")
102		}
103		// 纠正后同清单号可成功（失败不占号）。
104		mustManifest(t, s, "MBAD", "站点A", []string{"P004"}, tClock(2026, 10, 5, 9, 45))
105	}
106	
107	// 待出站成员不能首次交接、退回、发运、直接 dispatch 或加入另一清单；
108	// 涉及它的批量操作整批拒绝（其他成员不变）。冻结与解除允许，预留保留。
109	func TestReservedParcelBlocksFlows(t *testing.T) {
110		s, _ := manifestStore(t)
111		mustManifest(t, s, "M1", "站点A", []string{"P001", "P002"}, tClock(2026, 10, 5, 9, 30))
112		tn := tClock(2026, 10, 5, 10, 0)
113	
114		if _, _, err := s.Handoff("H1", "站点A", "站点B", []string{"P001", "P003"}, tn); err == nil {
115			t.Fatal("涉及预留件的交接应整批拒绝")
116		}
117		if p, _ := s.Query("P003"); p.Station != "站点A" {
118			t.Fatalf("整批拒绝不得移动其他成员 P003: %+v", p)
119		}
120		if _, _, err := s.Dispatch("B1", "站点A", "张三", []string{"P003", "P002"}, tn); err == nil {
121			t.Fatal("涉及预留件的直接 dispatch 应整批拒绝")
122		}
123		if _, err := s.BatchQuery("B1"); err == nil {
124			t.Fatal("失败的 dispatch 不得占用批次号")
125		}
126		if _, _, err := s.Ship("S1", "站点A", "站点B", []string{"P001"}, tn); err == nil {
127			t.Fatal("预留件不能首次发运")
128		}
129		if _, _, err := s.CreateManifest("M2", "站点A", []string{"P003", "P001"}, tn); err == nil {
130			t.Fatal("预留件不能加入另一清单，整单应拒绝")
131		}
132		if s.data.Manifests["M2"] != nil {
133			t.Fatal("失败的清单创建不得占用 M2")
134		}
135		// 预留件不能退回：先制造一个可退回的旧交接给 P002（预留之前不可能交接后预留，
136		// 故此处直接验证交接 H 给 P003 不受影响即可；退回场景在取消测试中覆盖）。
137	
138		// 冻结与解除允许，预留保留。
139		mustFreeze(t, s, "E1", "P001", "站点A", "外包装破损", tClock(2026, 10, 5, 10, 30))
140		if m := s.ActiveManifest("P001"); m == nil || m.Manifest != "M1" {
141			t.Fatal("冻结后预留应保留")
142		}
143		if _, _, err := s.Unfreeze("U1", "E1", "核实放行", tClock(2026, 10, 5, 11, 0)); err != nil {
144			t.Fatalf("预留件解除冻结应允许: %v", err)
145		}
146		if m := s.ActiveManifest("P001"); m == nil || m.Manifest != "M1" {
147			t.Fatal("解除冻结后预留应保留")
148		}
149		if p, _ := s.Query("P001"); p.Status != statusInStation {
150			t.Fatalf("解除冻结后应恢复在站: %+v", p)
151		}
152	}
153	
154	// 确认出站：按原顺序创建普通配送批次、释放预留，成员转配送中并追加出站轨迹；
155	// 后续配送作业照常，dispatch 可按该批次原内容重放。
